import { lazy, Suspense } from 'react';
import styles from './Chart.module.scss';

// Lazy load the Chart component with dynamic import optimization
const Chart = lazy(() => 
  import(
    /* webpackChunkName: "chart-component" */
    /* webpackPreload: true */
    './Chart'
  )
);

/**
 * Lazy-loaded Chart component wrapper with loading state
 */
const ChartLazy = (props) => {
  return (
    <Suspense 
      fallback={
        <div className={`${styles.chart} ${styles.loading}`} data-variant="default" data-size="medium">
          <div className={styles.loadingSpinner} role="status" aria-label="Loading chart">
            <div className={styles.spinner}></div>
            <span className={styles.loadingText}>Loading chart...</span>
          </div>
        </div>
      }
    >
      <Chart {...props} />
    </Suspense>
  );
};

export default ChartLazy;